actions.handler:
() => {
                        if (isMeasured(line.product)) {
                          if (stepUp(line.product, line.qty) === line.qty) { setQuantityNotice((current) => ({ ...current, [line.key]: t("m.maxAvailable", { amount: formatAmount(line.product, line.qty) }) })); return; }
                          setQuantityNotice((current) => { const next = { ...current }; delete next[line.key]; return next; });
                          increment(line.product.id, undefined, line.product);
                          return;
                        }
                        const available = line.variant ? line.variant.stock : line.product.stock;
                        if (line.qty >= 1000) {
                          setQuantityNotice((current) => ({ ...current, [line.key]: "Maximum 1000 packs of one variant per order." }));
                          return;
                        }
                        if (available !== undefined && line.qty >= available) {
                          setQuantityNotice((current) => ({ ...current, [line.key]: `Only ${available} pack(s) are currently available.` }));
                          return;
                        }
                        setQuantityNotice((current) => { const next = { ...current }; delete next[line.key]; return next; });
                        increment(line.product.id, line.variant?.id);
                      }

